use vstd::prelude::*;

verus! {
    fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
        requires
            numbers.len() <= 0x1_0000_0000, // Ensure the length of the input does not exceed u32::MAX
        ensures
            if numbers.len() == 0 {
                res.len() == 0
            } else {
                res.len() == 2 * numbers.len() - 1 &&
                forall |i: nat| (i < numbers.len() ==> res[2 * i] == numbers[i]) &&
                forall |i: nat| (i < numbers.len() - 1 ==> res[2 * i + 1] == delim)
            },
    {
        let n = numbers.len();
        let mut res = Vec::with_capacity(2 * n - 1);
        
        if n == 0 {
            return res; // Return empty array if input is empty
        }

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                res.len() == 2 * i, // The length of res should be 2 * i at the start of each iteration
                forall |j: nat| (j < i ==> res[2 * j] == numbers[j]) &&
                forall |j: nat| (j < i - 1 ==> res[2 * j + 1] == delim),
            decreases n - i,
        {
            res.push(numbers[i]); // Add the current number
            if i < n - 1 {
                res.push(delim); // Add the delimiter if not the last element
            }
            i = i + 1;
        }
        
        res
    }
}
